    public const str TOStatusInfoEvent          = 'TransferOrder.TransferStatus';
    public const str TOReceiptErrorEvent        = 'TransferOrder.ReceiptError';
    public const str TOPickedInfoEvent          = 'TransferOrder.Picked';
    public const str SOCancelBackOrderEvent     = 'SalesOrder.CancelBackOrders';
    public const str POApprovalErrorEvent       = 'PurchaseOrder.ApprovalError';
    public const str SOCreditCheckErrorEvent    = 'SalesOrder.CreditCheckError';
    public const str SOCreditCheckInfoEvent     = 'SalesOrder.CreditCheck';
    public const str ABNValidationEvent         = 'ABNValidation.Validated';
